import { TopicItem } from '../types';

type Lesson = Pick<TopicItem, 'summary' | 'lessonSections' | 'example' | 'references' | 'quickQuestions'>;
type Seed = [summary: string, example: string, prompt: string, answer: 'certo' | 'errado', explanation: string];

const make = (id: string, [summary, example, prompt, correctAnswer, explanation]: Seed): Lesson => ({
  summary,
  lessonSections: [{ heading: 'Como resolver', body: summary }],
  example,
  quickQuestions: [{ id: `${id}-q1`, prompt, source: 'Questão autoral para treino', correctAnswer, explanation }],
});

